"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["46338"],{48142(e){e.exports=JSON.parse('{"id":"FIN-442","slug":"at-the-money","term":"At-the-Money","also_known_as":[],"difficulty":"Intermediate","definition":"An option is at the money when its strike price is equal to, or very close to, the current price of the underlying asset.","explanation":["At-the-money options have little or no intrinsic value. Their price is made up almost entirely of time value, which reflects the chance of the underlying asset moving in the option holder\'s favour before expiry.","For example, if a share trades at 50, both a call and a put with a strike price of 50 are at the money. If the share is at 50.30, options with a 50 strike are often still described as at the money, or near the money.","At-the-money options usually have the highest time value of any strike price, because there is the greatest uncertainty about whether they will end up in or out of the money. Their price changes by roughly half as much as the underlying asset for small moves, because there is about an equal chance of the option finishing profitably or not.","Traders often use at-the-money options in strategies designed to profit from large price movements in either direction, such as straddles, or to earn premium income by selling options when they expect little movement. Their prices are also widely used to measure the market\'s expected volatility."],"note":"","total":1500,"prev":{"slug":"assumption","term":"Assumption"},"next":{"slug":"audit","term":"Audit"}}')}}]);